# MALE cosplay archetypes: title | 3 garments | 3 headgear/hair/face | 3 details | 3 props   (original archetypes, no named characters)
ARCH=[]
def A(t,g,h,d,p): ARCH.append((t,g.split('|'),h.split('|'),d.split('|'),p.split('|')))
